<script setup>
import{ref,reactive,computed,watch}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import api from'../services/api.js';import{User,Document,Edit,Star,Pointer,UserFilled,Clock,Guide,Bell,Setting,Search,Warning}from'@element-plus/icons-vue'
const route=useRoute(),loading=ref(true),profile=ref(null),items=ref([]),editing=ref(false),form=reactive({nickname:'',city:'',bio:'',preferences:'',avatar:'',coverImage:''});const section=computed(()=>route.meta.section||'profile')
const menus=[['profile','/user/profile','我的主页',User],['guides','/user/guides','我的攻略',Document],['drafts','/user/drafts','草稿箱',Edit],['routes','/user/routes','我的路线',Guide],['favorites','/user/favorites','我的收藏',Star],['likes','/user/likes','我的点赞',Pointer],['following','/user/following','我的关注',UserFilled],['followers','/user/followers','我的粉丝',User],['history','/user/history','浏览历史',Clock],['searches','/user/history?tab=search','搜索历史',Search],['reports','/user/reports','我的举报',Warning],['messages','/user/messages','消息中心',Bell],['settings','/user/settings','账号设置',Setting]]
const titles={profile:'我的主页',guides:'我的攻略',drafts:'草稿箱',routes:'我的路线',favorites:'我的收藏',likes:'我的点赞',following:'我的关注',followers:'我的粉丝',history:'浏览历史',searches:'搜索历史',reports:'我的举报',messages:'消息中心',settings:'账号设置'}
const statusLabels={DRAFT:'草稿',PENDING:'待审核',REJECTED:'审核未通过',PUBLISHED:'已发布',OFFLINE:'已下架'}
const reportStatusLabels={PENDING:'待处理',VALID:'举报成立',INVALID:'举报不成立',CLOSED:'已关闭'}
const targetLabels={GUIDE:'攻略',COMMENT:'评论'}
const itemLink=item=>{if(section.value==='guides'||section.value==='drafts')return`/user/guide/${item.id}`;if(section.value==='messages'&&item.message_type==='REPORT_RESULT')return'/user/reports';if(section.value==='messages'&&item.business_type==='GUIDE'&&item.business_id)return`/user/guide/${item.business_id}`;if(item.guide_id)return`/guide/${item.guide_id}`;if(item.title)return`/guide/${item.id}`;if(item.nickname)return`/creator/${item.id}`;return'#'}
const load=async()=>{loading.value=true;try{profile.value=await api.get('/user/profile');Object.assign(form,profile.value);if(section.value==='guides')items.value=(await api.get('/user/guides')).records||[];else if(section.value==='drafts')items.value=(await api.get('/user/guides',{params:{status:'DRAFT'}})).records||[];else if(section.value!=='profile'&&section.value!=='settings')items.value=await api.get(`/user/center/${section.value}`)}finally{loading.value=false}};watch(()=>route.fullPath,load,{immediate:true});const save=async()=>{try{profile.value=await api.put('/user/profile',form);editing.value=false;ElMessage.success('资料已保存')}catch(e){ElMessage.error(e.message)}};const read=async item=>{if(section.value==='messages'&&!item.is_read){await api.post(`/user/messages/${item.id}/read`);item.is_read=1}}
</script>
<template><div v-if="profile" class="center-page"><section class="profile-cover" :style="{backgroundImage:`linear-gradient(90deg,rgba(8,42,49,.76),rgba(8,42,49,.12)),url(${profile.coverImage})`}"><div class="container"><img :src="profile.avatar"><div><span>{{profile.role}} · {{profile.city}}</span><h1>{{profile.nickname}}</h1><p>{{profile.bio}}</p></div><button @click="editing=true">编辑个人资料</button></div></section><div class="profile-numbers"><div><b>{{profile.visitedCities}}</b><span>走过城市</span></div><div><b>{{profile.guideCount}}</b><span>攻略</span></div><div><b>{{profile.routeCount}}</b><span>路线</span></div><div><b>{{profile.followingCount}}</b><span>关注</span></div><div><b>{{profile.followerCount}}</b><span>粉丝</span></div><div><b>{{profile.receivedLikes}}</b><span>获赞</span></div></div><div class="container center-layout"><aside><router-link v-for="m in menus" :key="m[0]" :to="m[1]" :class="{active:section===m[0]}"><el-icon><component :is="m[3]"/></el-icon>{{m[2]}}</router-link></aside><main v-loading="loading"><div class="center-title"><div><span class="eyebrow">PERSONAL SPACE</span><h2>{{titles[section]}}</h2></div><router-link v-if="section==='guides'||section==='drafts'" to="/publish" class="create-link">+ 写一篇攻略</router-link></div><div v-if="section==='profile'" class="profile-intro"><div><h3>关于我</h3><p>{{profile.bio||'还没有填写个人简介。'}}</p></div><div><h3>旅行偏好</h3><p>{{profile.preferences||'还没有选择旅行偏好。'}}</p></div><div><h3>常住城市</h3><p>{{profile.city||'暂未填写'}}</p></div></div><div v-else-if="section==='settings'" class="settings-card"><h3>账号安全</h3><p>当前登录账号：{{profile.username}}</p><el-alert title="演示项目不会收集身份证、家庭住址等敏感信息。" type="success" :closable="false"/><el-button>修改密码</el-button></div><div v-else-if="section==='reports'&&items.length" class="report-list"><article v-for="item in items" :key="item.id"><div><span :class="['report-status',`is-${String(item.status).toLowerCase()}`]">{{reportStatusLabels[item.status]||item.status}}</span><small>{{item.create_time?.replace('T',' ').slice(0,16)}}</small></div><h3>{{item.target_title||`${targetLabels[item.target_type]||item.target_type} #${item.target_id}`}} · {{item.reason}}</h3><p>{{item.target_content||item.description||'目标内容当前不可用'}}</p><small v-if="item.description" class="report-description">举报说明：{{item.description}}</small><blockquote v-if="item.handle_note">处理说明：{{item.handle_note}}</blockquote></article></div><div v-else-if="items.length" class="center-items"><router-link v-for="item in items" :key="item.id" :to="itemLink(item)" class="center-item" @click="read(item)"><img v-if="item.cover_image||item.coverImage||item.avatar" :src="item.cover_image||item.coverImage||item.avatar"><div><span v-if="section==='guides'||section==='drafts'" :class="['guide-status',`is-${String(item.status).toLowerCase()}`]">{{statusLabels[item.status]||item.status}}</span><span v-else>{{item.create_time||item.createTime||item.status}}</span><h3>{{item.title||item.name||item.nickname||item.message_type}}</h3><p>{{item.summary||item.bio||item.content||item.description}}</p></div><i v-if="section==='messages'&&!item.is_read"></i></router-link></div><div v-else-if="!loading" class="empty-state"><span>○</span><h3>这里暂时还没有内容</h3><p>去发现一篇喜欢的攻略，或者写下自己的第一次分享。</p><router-link to="/guides">探索旅行攻略</router-link></div></main></div><el-dialog v-model="editing" title="编辑个人资料" width="min(560px,95%)"><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="form.nickname"/></el-form-item><el-form-item label="常住城市"><el-input v-model="form.city"/></el-form-item><el-form-item label="个人简介"><el-input v-model="form.bio" type="textarea" :rows="3"/></el-form-item><el-form-item label="旅行偏好"><el-input v-model="form.preferences" placeholder="例如：城市漫步,摄影,美食"/></el-form-item><el-form-item label="头像地址"><el-input v-model="form.avatar"/></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div><div v-else class="loading-panel"><el-skeleton :rows="12" animated/></div></template>
<style scoped>.profile-cover{height:310px;background-size:cover;background-position:center;color:white;display:flex;align-items:end;padding-bottom:35px}.profile-cover>div{display:grid;grid-template-columns:100px 1fr auto;gap:22px;align-items:center}.profile-cover img{width:100px;height:100px;border-radius:50%;object-fit:cover;border:4px solid white}.profile-cover span{font-size:10px;letter-spacing:2px;color:#c2ebed}.profile-cover h1{font:36px Georgia,"Songti SC",serif;margin:7px 0}.profile-cover p{margin:0;color:rgba(255,255,255,.8)}.profile-cover button{border:1px solid white;background:rgba(255,255,255,.12);color:white;border-radius:19px;padding:9px 15px}.profile-numbers{background:white;border-bottom:1px solid #e0e8e7;display:flex;justify-content:center;gap:65px;padding:18px}.profile-numbers div{text-align:center}.profile-numbers b{display:block;font:22px Georgia}.profile-numbers span{font-size:10px;color:#7b8f92}.center-layout{display:grid;grid-template-columns:210px 1fr;gap:40px;padding:45px 0 90px}.center-layout aside{display:flex;flex-direction:column;gap:3px}.center-layout aside a{display:flex;gap:10px;align-items:center;padding:11px 14px;border-radius:9px;color:#5d767b;font-size:13px}.center-layout aside a.active{background:#e4f1ef;color:#167c8c;font-weight:700}.center-title{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #dce6e5;padding-bottom:17px;margin-bottom:22px}.center-title h2{font:29px Georgia,"Songti SC",serif;margin:6px 0}.create-link{background:#167c8c;color:white;border-radius:18px;padding:9px 14px;font-size:12px}.profile-intro{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px}.profile-intro>div,.settings-card{background:white;border:1px solid #dce6e5;border-radius:14px;padding:22px}.profile-intro h3,.settings-card h3{font:19px Georgia,"Songti SC",serif}.profile-intro p,.settings-card p{color:#6a8084;line-height:1.8;font-size:13px}.settings-card .el-button{margin-top:20px}.center-items{display:grid;gap:12px}.center-item{min-height:110px;background:white;border:1px solid #dce6e5;border-radius:13px;display:grid;grid-template-columns:150px 1fr;overflow:hidden;position:relative}.center-item>img{width:150px;height:100%;object-fit:cover}.center-item>div{padding:16px}.center-item span{font-size:10px;color:#8ca0a3}.center-item .guide-status{display:inline-flex;border-radius:12px;padding:4px 9px;background:#eef3f3;color:#667b7f;font-weight:700}.center-item .guide-status.is-pending{background:#fff3d9;color:#a26a08}.center-item .guide-status.is-published{background:#e6f5ec;color:#2f8050}.center-item .guide-status.is-rejected{background:#ffebe7;color:#b14f3d}.center-item .guide-status.is-offline{background:#eef0f2;color:#637079}.center-item h3{margin:5px 0;font:18px Georgia,"Songti SC",serif}.center-item p{margin:0;color:#6c8286;font-size:12px;line-height:1.6}.center-item>i{position:absolute;right:14px;top:14px;width:8px;height:8px;border-radius:50%;background:#df7d4c}.report-list{display:grid;gap:12px}.report-list article{background:white;border:1px solid #dce6e5;border-radius:13px;padding:20px}.report-list article>div{display:flex;justify-content:space-between;align-items:center}.report-list small{color:#8a9b9e}.report-list h3{font:18px Georgia,"Songti SC",serif;margin:12px 0 6px}.report-list p{color:#6c8286;font-size:13px}.report-list .report-description{display:block;margin-top:8px}.report-list blockquote{margin:13px 0 0;padding:11px 14px;border-left:3px solid #167c8c;background:#edf6f4;color:#4a6c72;font-size:12px}.report-status{display:inline-flex;border-radius:13px;padding:5px 10px;background:#eef1f2;color:#66777a;font-size:11px;font-weight:700}.report-status.is-pending{background:#fff3d9;color:#9c670a}.report-status.is-valid{background:#ffebe7;color:#ae4a38}.report-status.is-invalid{background:#e7f4ec;color:#377d53}.empty-state{text-align:center;padding:80px;background:white;border:1px dashed #cfdedc;border-radius:15px}.empty-state>span{font-size:38px;color:#8fc8c6}.empty-state h3{font:22px Georgia,"Songti SC",serif}.empty-state p{color:#7b8e92}.empty-state a{color:#167c8c;font-weight:700}@media(max-width:760px){.profile-cover>div{grid-template-columns:75px 1fr}.profile-cover img{width:75px;height:75px}.profile-cover button{grid-column:2;justify-self:start}.profile-cover h1{font-size:28px}.profile-numbers{justify-content:start;overflow:auto;gap:30px}.profile-numbers div{min-width:55px}.center-layout{grid-template-columns:1fr;padding-top:20px}.center-layout aside{flex-direction:row;overflow:auto;padding-bottom:8px}.center-layout aside a{white-space:nowrap}.profile-intro{grid-template-columns:1fr}.center-item{grid-template-columns:100px 1fr}.center-item>img{width:100px}}</style>
